if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  if (args.shift() !== '--benchmark') throw Error('Use --benchmark [--samples32] [--directory NEW_EXTERNAL_DIRECTORY].');
