  description: 'The same five-cutoff ranking with separately indexed shade-aware color tolerance. Gives darker chromatic shades more credit while preserving neutral lightness matching.',
  profile: 'all-levels', metric: 'shade-aware', family: 'cutoff-quality', representation: 'shade-coverage-quality-1024', searchKind: 'cutoff',
  approximate: false, limitations: SHADE_LIMITATIONS,
